import{_ as e,o as a,c as s,a5 as n}from"./chunks/framework.BYXPg_yw.js";const g=JSON.parse('{"title":"Reporting an issue on GitHub","description":"","frontmatter":{"layout":"doc","outline":"deep","title":"Reporting an issue on GitHub"},"headers":[],"relativePath":"manual/support/github-issue.md","filePath":"manual/support/github-issue.md","lastUpdated":1792759058000}'),i={name:"manual/support/github-issue.md"};function o(r,t,l,h,p,d){return a(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="reporting-an-issue-on-github" tabindex="-1">Reporting an issue on GitHub <a class="header-anchor" href="#reporting-an-issue-on-github" aria-label="Permalink to &quot;Reporting an issue on GitHub&quot;">​</a></h1><p>When something in the software does not work — on the robot, or while you develop with the SDK or the simulator — this is how to report it on <a href="https://github.com/RainbowRobotics/RBQ/issues" target="_blank" rel="noreferrer">RainbowRobotics/RBQ issues</a> as &quot;this does not work, please take a look&quot;. The first step comes before you write anything: <strong>check again on the latest nightly.</strong></p><h2 id="where" tabindex="-1">Where to file <a class="header-anchor" href="#where" aria-label="Permalink to &quot;Where to file {#where}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you have</th><th>Where it goes</th></tr></thead><tbody><tr><td>Software that does not work on the robot, app, SDK or simulator</td><td><strong><a href="https://github.com/RainbowRobotics/RBQ/issues" target="_blank" rel="noreferrer">GitHub Issues</a></strong> — this page</td></tr><tr><td>A question about usage, settings or specifications</td><td><a href="https://github.com/RainbowRobotics/RBQ/discussions" target="_blank" rel="noreferrer">GitHub Discussions</a></td></tr><tr><td>A fault that needs inspection or repair</td><td><a href="/RBQ/nightly/manual/support/#where-to-send">A/S support request</a></td></tr><tr><td>Anything that must not be public (private · business · licensing)</td><td><a href="mailto:rbq.support@rainbow-robotics.com" target="_blank" rel="noreferrer">rbq.support@rainbow-robotics.com</a></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">⚠ Anyone can read an issue</p><p>The repository is public, so everything you post and attach is public too. Do not post customer or site details, passwords, or photos and videos with people in them. Send that kind of material to the email above.</p></div><h2 id="nightly-first" tabindex="-1">1. Check again on the latest nightly <a class="header-anchor" href="#nightly-first" aria-label="Permalink to &quot;1. Check again on the latest nightly {#nightly-first}&quot;">​</a></h2><p>Issues are checked against the <strong>latest nightly</strong>. A nightly comes out every night with every fix made up to that day, so a problem you hit on the stable release may already be fixed. Bring the app and the robot — and the SDK or simulator, if you use them — up to the latest nightly, repeat the same steps, and report <strong>only what still fails</strong>.</p><h3 id="nightly-app" tabindex="-1">The app <a class="header-anchor" href="#nightly-app" aria-label="Permalink to &quot;The app {#nightly-app}&quot;">​</a></h3><p>Install the nightly app from the nightly docs&#39; <a href="https://rainbowrobotics.github.io/RBQ/nightly/manual/downloads/" target="_blank" rel="noreferrer">Downloads</a> page: <strong>RBQ Nightly</strong> on Android and on Linux · Steam Deck, the <strong>TestFlight</strong> beta on iPhone and iPad.</p><p>If it is already installed, look at the <strong>GUI Version</strong> line under <strong>Maintenance → Software update</strong>. If an update button shows, press it to bring the app up to date; if it reads <code>You&#39;re on the latest version</code>, you are set.</p><h3 id="nightly-robot" tabindex="-1">Robot software <a class="header-anchor" href="#nightly-robot" aria-label="Permalink to &quot;Robot software {#nightly-robot}&quot;">​</a></h3><p>In the nightly app, <strong>Maintenance → Software update</strong> lists nightly builds only. <code>Download</code> the build marked <code>Latest</code>, send it with <code>Send robot software</code>, and reboot with the robot sitting down. The steps and cautions are on <a href="/RBQ/nightly/manual/gui/software-update.html">Software Update</a>.</p><p>Without the app, pick the <code>(nightly)</code> entry on the <strong>Software</strong> card of the robot&#39;s <a href="/RBQ/nightly/software/developers-guide.html#web-ui">web UI</a> <strong>Dashboard</strong> and press <code>Update</code>.</p><h3 id="nightly-sdk" tabindex="-1">SDK · simulator <a class="header-anchor" href="#nightly-sdk" aria-label="Permalink to &quot;SDK · simulator {#nightly-sdk}&quot;">​</a></h3><p>The repository&#39;s <code>nightly</code> branch is the same source as the latest nightly. Use the commands below instead of the <code>git clone</code> in the <a href="/RBQ/nightly/guides/sdk-cpp/quick-start.html">C++</a> · <a href="/RBQ/nightly/guides/sdk-python/quick-start.html">Python</a> · <a href="/RBQ/nightly/guides/sdk-ros/quick-start.html">ROS 2</a> quick starts; the remaining steps are the same.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nightly</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --single-branch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/RainbowRobotics/RBQ.git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RBQ-nightly</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RBQ-nightly</span></span></code></pre></div><p>The <code>nightly</code> branch is recreated every night with no earlier history, so <code>git pull</code> fails on it. Bring a folder you already have up to date with the two lines below, then run the quick start&#39;s build steps again.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nightly</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nightly</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin/nightly</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">⚠ If the robot is in field use</p><p>Nightlies do not go through release verification (<a href="/RBQ/nightly/software/release-note/#channels">Stable and nightly</a>). To put the robot back into field use after you have checked, return it to the stable release with <a href="/RBQ/nightly/manual/troubleshooting/version-rollback.html">Version rollback</a>.</p></div><h2 id="versions" tabindex="-1">2. Write down the versions <a class="header-anchor" href="#versions" aria-label="Permalink to &quot;2. Write down the versions {#versions}&quot;">​</a></h2><p>A nightly version ends in <code>-nightly.&lt;8-character commit&gt;</code>, so that one string pins the exact build. The app and robot versions are both on the <strong>Maintenance → Software update</strong> screen.</p><table tabindex="0"><thead><tr><th>What to write</th><th>Where to read it</th></tr></thead><tbody><tr><td><strong>App version</strong></td><td>The <strong>GUI Version</strong> line. The <code>NIGHTLY</code> badge must be there for it to be the nightly app</td></tr><tr><td><strong>Robot version</strong></td><td><code>Version</code> on the <code>Current robot</code> card</td></tr><tr><td><strong>Do the app and robot match</strong></td><td><code>Matches robot</code> or <code>Differs from robot</code> next to the <strong>GUI Version</strong> line</td></tr><tr><td><strong>SDK · simulator version</strong> (if you use them)</td><td>The <code>version:</code> line at the top of <code>nightly.txt</code> in the cloned folder</td></tr></tbody></table><h2 id="write" tabindex="-1">3. Write the issue <a class="header-anchor" href="#write" aria-label="Permalink to &quot;3. Write the issue {#write}&quot;">​</a></h2><p>Opening a <a href="https://github.com/RainbowRobotics/RBQ/issues/new" target="_blank" rel="noreferrer">new issue</a> gives you an empty editor (you need a GitHub account). Put what does not work in the <strong>title</strong> in one line, then copy the block below into the body and fill it in. Korean or English is fine. If you have several problems, file one issue for each.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[What does not work]</span></span>
<span class="line"><span>One line. (e.g. The robot collapses about 3 s after switching to WALK)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Versions — latest nightly]</span></span>
<span class="line"><span>App: v1.2609.0-nightly.b5635a91 (NIGHTLY)</span></span>
<span class="line"><span>Robot: 1.2609.0-nightly.b5635a91 (Matches robot)</span></span>
<span class="line"><span>SDK · simulator: v1.2609.0-nightly.b5635a91 (if used, nightly.txt)</span></span>
<span class="line"><span>On an earlier version: worked (last good v1.2609.0) / same problem / don&#39;t know</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Environment]</span></span>
<span class="line"><span>Real robot / simulator (MuJoCo · Gazebo)</span></span>
<span class="line"><span>App on: Android · iPhone/iPad · Linux · Steam Deck · web UI</span></span>
<span class="line"><span>SDK: C++ · Python · ROS 2 (if used)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Steps]</span></span>
<span class="line"><span>1. Robot on level ground, auto start completed</span></span>
<span class="line"><span>2. STAND → WALK</span></span>
<span class="line"><span>3. Push the left joystick forward</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Expected]</span></span>
<span class="line"><span>The robot walks forward.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Actual]</span></span>
<span class="line"><span>It collapses about 3 s later. App log shows:</span></span>
<span class="line"><span>[ERROR] ...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[How often]</span></span>
<span class="line"><span>8 times out of 10</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Attached]</span></span>
<span class="line"><span>Black Box zip, screenshots, the code that fails (SDK)</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">⚠ Paste error messages verbatim</p><p>Do not summarize or retype an error message. A few characters&#39; difference is enough to make it unfindable. Copy the line as it appeared, even if it is long.</p></div><p>Drag files into the editor to attach them.</p><ul><li><strong>Black Box zip</strong> — the most useful thing for anything momentary, such as a fall or an emergency stop. How to make one is in <a href="/RBQ/nightly/manual/support/#blackbox-zip">Black Box zip</a>.</li><li><strong>System log</strong> — download it as in <a href="/RBQ/nightly/manual/support/#system-log">System log</a> and zip it.</li><li><strong>SDK code</strong> — cut the failing part down to a few lines and paste it as a code block.</li><li><strong>Walking problems</strong> — also give the payload you have fitted and the values entered in the app (<a href="/RBQ/nightly/manual/support/#payload">The payload you have fitted</a>).</li></ul><h2 id="after" tabindex="-1">4. After you file <a class="header-anchor" href="#after" aria-label="Permalink to &quot;4. After you file {#after}&quot;">​</a></h2><ul><li>Replies come as comments on the issue. If more detail is asked for, add it as a comment on the same issue rather than opening a new one.</li><li>Once it is fixed, the issue is told which nightly carries the fix and is closed. The fix is also in the next stable release.</li><li>If that nightly still shows the problem, file a new issue and include the earlier issue number (<code>#number</code>).</li><li>If the team decides not to change it, the issue is told so and closed.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also {#see-also}&quot;">​</a></h2><ul><li><a href="/RBQ/nightly/manual/support/">Requesting support (C/S · A/S)</a> — usage questions, repairs, and making logs to attach</li><li><a href="/RBQ/nightly/manual/gui/software-update.html">Software Update</a> — checking and updating the app and robot versions</li><li><a href="/RBQ/nightly/software/release-note/#channels">Stable and nightly</a> — how the two channels differ</li><li><a href="/RBQ/nightly/manual/troubleshooting/version-rollback.html">Version rollback</a> — going back to stable</li></ul>`,32)])])}const u=e(i,[["render",o]]);export{g as __pageData,u as default};
